/**
 * Robust PDF Generation Utility using html2canvas-pro + jsPDF.
 * 
 * Unlike standard html2canvas / html2pdf.js, html2canvas-pro natively supports
 * modern CSS color functions (lab, oklab, oklch) generated by Tailwind CSS v4.
 */

function loadScript(src: string): Promise<void> {
  return new Promise((resolve, reject) => {
    if (typeof document === "undefined") return resolve();
    if (document.querySelector(`script[src="${src}"]`)) {
      resolve();
      return;
    }
    const script = document.createElement("script");
    script.src = src;
    script.crossOrigin = "anonymous";
    script.onload = () => resolve();
    script.onerror = () => reject(new Error(`Failed to load script: ${src}`));
    document.head.appendChild(script);
  });
}

async function preparePDFDoc(element: HTMLElement): Promise<{ pdf: any; jsPDF: any } | null> {
  // 1. Ensure jsPDF is loaded
  if (!(window as any).jspdf) {
    await loadScript("https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js");
  }

  // 2. Ensure html2canvas-pro is loaded (supports lab/oklch/oklab)
  if (!(window as any).html2canvas) {
    await loadScript("https://cdn.jsdelivr.net/npm/html2canvas-pro@2.6.3/dist/html2canvas-pro.min.js");
  }

  const html2canvas = (window as any).html2canvas;
  const { jsPDF } = (window as any).jspdf;

  if (!html2canvas || !jsPDF) {
    throw new Error("PDF generation engines failed to initialize");
  }

  // 3. Clone target to render at crisp A4 printable dimensions (210mm = ~794px)
  const clone = element.cloneNode(true) as HTMLElement;
  clone.style.transform = "none";
  clone.style.margin = "0";
  clone.style.padding = "24px";
  clone.style.boxShadow = "none";
  clone.style.width = "794px";
  clone.style.position = "fixed";
  clone.style.top = "-99999px";
  clone.style.left = "-99999px";
  clone.style.zIndex = "-9999";
  document.body.appendChild(clone);

  try {
    const canvas = await html2canvas(clone, {
      scale: 2,
      useCORS: true,
      logging: false,
      scrollY: 0,
      scrollX: 0,
      windowWidth: 794,
    });

    const pdf = new jsPDF({
      orientation: "portrait",
      unit: "mm",
      format: "a4",
    });

    const imgData = canvas.toDataURL("image/jpeg", 0.98);
    const pdfWidth = pdf.internal.pageSize.getWidth();
    const pdfHeight = (canvas.height * pdfWidth) / canvas.width;

    const pageHeight = pdf.internal.pageSize.getHeight();
    if (pdfHeight <= pageHeight) {
      pdf.addImage(imgData, "JPEG", 0, 0, pdfWidth, pdfHeight);
    } else {
      let heightLeft = pdfHeight;
      let position = 0;
      pdf.addImage(imgData, "JPEG", 0, position, pdfWidth, pdfHeight);
      heightLeft -= pageHeight;
      while (heightLeft > 0) {
        position = heightLeft - pdfHeight;
        pdf.addPage();
        pdf.addImage(imgData, "JPEG", 0, position, pdfWidth, pdfHeight);
        heightLeft -= pageHeight;
      }
    }

    return { pdf, jsPDF };
  } finally {
    if (clone.parentNode) {
      document.body.removeChild(clone);
    }
  }
}

export async function exportElementToPDF(element: HTMLElement, filename: string): Promise<void> {
  try {
    const result = await preparePDFDoc(element);
    if (result) {
      result.pdf.save(filename);
    }
  } catch (error) {
    console.error("PDF generation failed, falling back to print dialog:", error);
    window.print();
  }
}

export async function generatePDFFile(element: HTMLElement, filename: string): Promise<File | null> {
  try {
    const result = await preparePDFDoc(element);
    if (!result) return null;
    const blob = result.pdf.output("blob");
    return new File([blob], filename, { type: "application/pdf" });
  } catch (e) {
    console.error("Failed to generate PDF file object:", e);
    return null;
  }
}
